/* Original formative questions. Each criterion is worth one mark. */
const practiceSets = [
  {id:'year11-pilot',revision:1,year:11,title:'Year 11 · Foundations in context',minutes:45,
    description:'Python, data, databases and security. Eight short answers and two extended responses; 30 marks.',
    questions:[
      {id:'y11-1',type:'Short answer',title:'Trace a selection',topic:'Programming',chapter:'selection',
        prompt:'Write the exact output, in order, for this Python program.',
        code:'score = 7\nif score >= 5:\n    score = score + 2\nelse:\n    score = score - 1\nprint(score)\nprint(score > 10)',
        criteria:['First output is 9.','Second output is False (Python Boolean spelling).'],
        model:'9\nFalse\nThe condition is true, so 2 is added to 7. Nine is not greater than ten.',
        mistake:'Do not execute both branches or print the condition instead of the final comparison.'},
      {id:'y11-2',type:'Short answer',title:'Represent a value',topic:'Data representation',chapter:'representation',
        prompt:'Convert decimal 45 to an eight-bit binary value. Show a place-value calculation to support your answer.',
        criteria:['Binary result is 00101101.','Working correctly combines place values 32 + 8 + 4 + 1 = 45.'],
        model:'00101101\n32 + 8 + 4 + 1 = 45. The 128, 64, 16 and 2 positions are zero.',
        mistake:'Write all eight bits. Correct equivalent place-value working is acceptable.'},
      {id:'y11-3',type:'Short answer',title:'Validation and verification',topic:'Data quality',chapter:'database-foundations',
        prompt:'A club enters member ages from paper forms. Explain the difference between validating an age and verifying the entered age.',
        criteria:['Validation checks whether an age meets stated rules, such as an integer within an allowed range.','Verification checks that the entered age matches the source form; it does not establish that the original age is true.'],
        model:'Validation checks an age against rules, such as a permitted numeric range. Verification compares the entered age with the paper form to check it was copied accurately. An incorrect age on the form can still be copied correctly.',
        mistake:'A valid value is not necessarily the true age. Award equivalent explanations without requiring the model wording.'},
      {id:'y11-4',type:'Short answer',title:'Choose a primary key',topic:'Databases',chapter:'entities-relationships',
        prompt:'A Member table has MemberID, GivenName and FamilyName. MemberID is unique and never empty. Explain why MemberID is a better primary key than FamilyName.',
        criteria:['MemberID uniquely identifies each member record.','Family names may repeat, so FamilyName cannot reliably identify one record.'],
        model:'Each MemberID identifies exactly one member. Two members can share a family name, making FamilyName unsuitable as a unique identifier.',
        mistake:'Do not assume names are unique. A primary key also cannot be null.'},
      {id:'y11-5',type:'Short answer',title:'Filter a table',topic:'SQL',chapter:'sql-basics',
        prompt:'Loan(LoanID, MemberID, Returned) stores Returned as 0 for an active loan and 1 for a returned loan. Write SQL to display only LoanID for active loans.',
        criteria:['SELECT LoanID FROM Loan identifies the required field and table.','WHERE Returned = 0 correctly filters active loans.'],
        model:'SELECT LoanID\nFROM Loan\nWHERE Returned = 0;\nSQL keyword case and a missing final semicolon do not affect these marks. Equivalent SQL that returns the requested result is acceptable.',
        mistake:'Returned = 1 selects completed loans. Selecting every field does not meet the requested output.'},
      {id:'y11-6',type:'Short answer',title:'Respond to phishing',topic:'Security',chapter:'security-threats',
        prompt:'An unexpected email demands your school password through an unfamiliar link. Identify one warning sign from the scenario and one suitable response.',
        criteria:['Identifies the unexpected password request, unfamiliar link or pressure to act as a warning sign.','Does not use the link or disclose the password; reports it through the school process or verifies through a known independent channel.'],
        model:'The unfamiliar link requesting a password is suspicious. Do not follow it or send credentials; report the message using the school process. Independently contact support through a known address if needed.',
        mistake:'Replying to the suspicious sender is not independent verification. A warning sign is evidence for caution, not proof on its own.'},
      {id:'y11-7',type:'Short answer',title:'Trace a list',topic:'Programming',chapter:'arrays',
        prompt:'Write the final values of total and len(values) after this code runs.',
        code:'values = [4, 1, 3]\ntotal = 0\nfor value in values:\n    total = total + value',
        criteria:['Final total is 8.','len(values) is 3.'],
        model:'total = 8\nlen(values) = 3\nThe loop visits three items and adds each value once.',
        mistake:'The length counts items, not their sum. The loop does not alter the list.'},
      {id:'y11-8',type:'Short answer',title:'Test a boundary',topic:'Testing',chapter:'selection',
        prompt:'A program accepts an integer only when 1 <= quantity <= 5. Give one valid boundary input and one invalid input immediately outside a boundary, with the expected acceptance result for each.',
        criteria:['Gives 1 or 5 and correctly expects acceptance.','Gives 0 or 6 and correctly expects rejection.'],
        model:'1 → accepted.\n0 → rejected.\nAlternatively, 5 → accepted and 6 → rejected. Either appropriate boundary can be used for each part.',
        mistake:'A typical valid value such as 3 does not test a boundary. Include the expected result.'},
      {id:'y11-9',type:'Extended response',title:'Design a score summary',topic:'Programming and testing',chapter:'arrays',
        prompt:'A Pygame game stores each round score in a one-dimensional list. Scores are whole numbers from 0 to 50. Design an algorithm, using pseudocode or Python, to display the number of rounds, total score and highest score. Handle an empty list explicitly. Explain two useful tests, including inputs and expected results. You do not need to write Pygame drawing code.',
        criteria:['Checks for an empty list before trying to read its first item.','For an empty list, reports zero rounds/total and no highest score (or a clear no-rounds message).','For a non-empty list, correctly obtains the number of rounds.','Correctly accumulates the total across all items.','Correctly finds the maximum, with valid initialisation (for example, the first item).','Gives a non-empty test with correct expected count, total and maximum.','Gives an empty-list test with the expected no-rounds behaviour.'],
        model:'IF length(scores) = 0 THEN\n    DISPLAY "No rounds", 0, 0, "No highest score"\nELSE\n    total ← 0\n    highest ← scores[0]\n    FOR EACH score IN scores\n        total ← total + score\n        IF score > highest THEN\n            highest ← score\n        ENDIF\n    NEXT score\n    DISPLAY length(scores), total, highest\nENDIF\n\nTest [10, 0, 30]: 3 rounds, total 40, highest 30. Test []: zero rounds and total, no highest score. Correct equivalent algorithms are acceptable, including suitable built-ins because this question does not prohibit them.',
        mistake:'Do not index scores[0] before checking for an empty list. A test needs expected results, not just an input.'},
      {id:'y11-10',type:'Extended response',title:'Protect a club loan register',topic:'Databases and security',chapter:'entities-relationships',
        prompt:'A school club records members and equipment loans. Each member may have many loans; each loan belongs to one member. Design two related tables, identifying a primary key for each and the foreign key. Explain how the design avoids repeating member details in every loan. Then propose a staff access control and a recovery measure, explaining how each helps.',
        criteria:['Defines a Member table with MemberID as its primary key and suitable member fields.','Defines a Loan table with LoanID as its primary key and suitable loan fields.','Places MemberID as a foreign key in Loan referencing Member.MemberID.','Correctly describes the one-member-to-many-loans relationship.','Explains that storing member details once reduces duplication or inconsistent updates.','Proposes restricted staff accounts/permissions and explains limiting unauthorised access or changes.','Proposes regular backups with restore testing and explains recovery after loss/corruption.'],
        model:'Member(MemberID PK, GivenName, FamilyName)\nLoan(LoanID PK, MemberID FK, ItemDescription, DueDate, Returned)\nLoan.MemberID references Member.MemberID. One member can have many loans, while each loan references one member. Names are stored once in Member, so updating a name does not require editing every loan. Limit editing to authorised club staff using individual accounts and suitable permissions. Make regular separate backups and test restoration so records can be recovered after loss or corruption. Equivalent field choices and suitable explained controls are acceptable.',
        mistake:'Do not place a single LoanID in Member to represent all loans. Backups support recovery; they do not prevent unauthorised access.'}
    ]},
  {id:'year12-pilot',revision:1,year:12,title:'Year 12 · Applying and explaining',minutes:45,
    description:'Structures, algorithms, objects, relational data and security. Eight short answers and two extended responses; 30 marks.',
    questions:[
      {id:'y12-1',type:'Short answer',title:'Trace a two-dimensional list',topic:'Data structures',chapter:'unit3-structures',
        prompt:'State the final value of grid and the output of print.',
        code:'grid = [[1, 2], [3, 4]]\ngrid[1][0] = grid[0][1] + 5\nprint(grid[1][0])',
        criteria:['Final grid is [[1, 2], [7, 4]].','Printed output is 7.'],
        model:'grid = [[1, 2], [7, 4]]\nOutput: 7\nThe right side reads 2, adds 5, and writes to row 1, column 0 using zero-based indices.',
        mistake:'Row and column indices are zero-based. Only one item changes.'},
      {id:'y12-2',type:'Short answer',title:'Select a dictionary',topic:'Data structures',chapter:'unit3-structures',
        prompt:'A game needs to retrieve item descriptions using unique item IDs. Explain why a dictionary is suitable, and what must be true about its keys.',
        criteria:['Explains mapping an item ID directly to its description/value for retrieval by that ID.','States that keys must be unique; duplicate IDs cannot represent two distinct entries under the same key.'],
        model:'A dictionary maps each item ID to its description, allowing retrieval by that ID rather than finding its position in a list. Each key must be unique; assigning an existing key replaces its associated value in Python.',
        mistake:'A dictionary key is not a numeric position. Do not claim dictionaries automatically reject duplicate assignments.'},
      {id:'y12-3',type:'Short answer',title:'Prepare for binary search',topic:'Algorithms',chapter:'unit3-search',
        prompt:'A list of unique scores will be searched with binary search. State its required ordering condition and explain why that condition matters.',
        criteria:['States that the list must be sorted according to the comparison order used by the algorithm.','Explains that comparing with the middle item then permits eliminating the half that cannot contain the target.'],
        model:'The scores must be sorted in the order assumed by the search, such as ascending order. A comparison with the middle score then identifies which half can contain the target, allowing the other half to be discarded.',
        mistake:'A list being indexed is insufficient. Without ordering, discarding half can discard the target.'},
      {id:'y12-4',type:'Short answer',title:'Trace a bubble-sort pass',topic:'Algorithms',chapter:'unit3-sort',
        prompt:'Starting with [5, 2, 4, 1], perform one left-to-right bubble-sort pass for ascending order. Compare adjacent pairs at indices (0,1), (1,2), then (2,3), swapping each out-of-order pair. State the resulting list and the value now at the final position.',
        criteria:['Resulting list is [2, 4, 1, 5].','Identifies 5 as the value at the final position.'],
        model:'[5,2,4,1] → [2,5,4,1] → [2,4,5,1] → [2,4,1,5].\nThe largest value, 5, reaches the final position after this pass.',
        mistake:'One pass does not fully sort this list. Follow the specified left-to-right convention.'},
      {id:'y12-5',type:'Short answer',title:'Explain method overriding',topic:'Object-oriented programming',chapter:'unit3-inheritance',
        prompt:'Player and Hazard inherit from Actor. Both subclasses define update(). Explain inheritance and overriding in this example.',
        criteria:['Explains that Player and Hazard inherit shared Actor behaviour/attributes, avoiding repeated common code.','Explains that a subclass supplies its own update implementation to specialise behaviour inherited from Actor.'],
        model:'Actor can define shared position and movement behaviour that Player and Hazard inherit. Each subclass overrides update() to specialise its behaviour, such as player input or a hazard patrol.',
        mistake:'Overriding changes a subclass implementation; it does not mean copying every base-class method.'},
      {id:'y12-6',type:'Short answer',title:'Join related records',topic:'SQL',chapter:'unit4-sql',
        prompt:'Member(MemberID, Name) and Loan(LoanID, MemberID) are related by MemberID. Write SQL to display Name and LoanID for matching members and loans.',
        criteria:['Selects Member.Name and Loan.LoanID from the two tables, allowing suitable aliases.','Correctly joins on Member.MemberID = Loan.MemberID.'],
        model:'SELECT Member.Name, Loan.LoanID\nFROM Member\nINNER JOIN Loan ON Member.MemberID = Loan.MemberID;\nEquivalent correct joins and aliases are acceptable. Keyword case and a missing final semicolon do not affect these marks.',
        mistake:'Joining Name to LoanID or omitting the relationship condition does not match the related records.'},
      {id:'y12-7',type:'Short answer',title:'Referential integrity',topic:'Relational databases',chapter:'unit4-design',
        prompt:'Loan.MemberID is a mandatory foreign key referencing Member.MemberID, and foreign-key enforcement is enabled. Explain what happens when a loan references a MemberID that does not exist, and why.',
        criteria:['States that the insert/update is rejected under the stated enforced constraint.','Explains that the constraint prevents an orphan loan and preserves references to existing members.'],
        model:'The operation is rejected because its MemberID does not reference an existing member. This prevents an orphan loan and maintains referential integrity.',
        mistake:'Do not assume a foreign-key label enforces itself in every environment; this question explicitly states enforcement is enabled.'},
      {id:'y12-8',type:'Short answer',title:'Choose a security control',topic:'Security',chapter:'unit4-controls',
        prompt:'A stolen password allows an attacker to attempt a staff account login. Propose one additional login control and explain one limitation of it.',
        criteria:['Proposes an additional authentication factor, preferably phishing-resistant MFA, that is independent of the stolen password.','Explains a relevant limitation such as recovery-channel compromise, stolen sessions, or phishing/push approval attacks for susceptible MFA methods.'],
        model:'Use phishing-resistant multi-factor authentication such as an appropriately configured security key. A stolen password alone would then be insufficient, but account recovery or an already-stolen authenticated session can still be attacked. If proposing one-time codes or push MFA, explain a limitation relevant to that method.',
        mistake:'Changing password length alone does not add a factor. No control removes every attack path.'},
      {id:'y12-9',type:'Extended response',title:'Model an interactive game',topic:'Structures, objects and testing',chapter:'unit3-objects',
        prompt:'A Pygame game uses an 8 × 10 tile map, item descriptions indexed by item ID, a keyboard-controlled player and patrolling hazards. Explain suitable data structures and a class design using Actor, Player and Hazard. Describe how one frame separates state updates from drawing. Propose two tests with expected results. You do not need to implement the complete game.',
        criteria:['Uses a two-dimensional list/array for tile values accessed by row and column.','Uses a dictionary mapping unique item IDs to descriptions or metadata.','Places shared position/movement behaviour in Actor and uses inheritance for Player and Hazard.','Explains overridden update behaviour for input-driven Player and patrol-driven Hazard.','Describes updating state before drawing that state, with drawing not changing gameplay values.','Gives a movement or wall-boundary test with a specific expected outcome.','Gives an item lookup or patrol test with a specific expected outcome.'],
        model:'Store tiles in a 2D list accessed as tiles[row][column], and descriptions in a dictionary such as items["key1"]. Actor holds common position and movement behaviour; Player and Hazard inherit it. Player.update reads input and Hazard.update advances a predictable patrol. Each frame processes events and updates game state before drawing that state. Drawing the HUD must not increment the score. For example, moving right into a wall must leave the player position unchanged; looking up "key1" must return its stated description. Equivalent designs and concrete tests meeting these requirements are acceptable.',
        mistake:'Naming classes is insufficient: explain responsibilities and inherited/overridden behaviour. A test requires an expected outcome.'},
      {id:'y12-10',type:'Extended response',title:'Design a reliable booking change',topic:'Database development and security',chapter:'unit4-sql',
        prompt:'A booking service stores Workshop(WorkshopID, Title, Capacity) and Booking(BookingID, WorkshopID, StudentID). A booking must refer to an existing workshop; a student must not book the same workshop twice. Staff can change capacity. Explain suitable database constraints, how the application should safely use user-supplied values in SQL, one suitable staff access control, and a recovery measure. Include an example check for the duplicate-booking rule.',
        criteria:['Identifies suitable primary keys for Workshop and Booking.','Enforces Booking.WorkshopID as a foreign key to an existing Workshop.','Uses a unique constraint on the pair (WorkshopID, StudentID) to prevent duplicate student bookings.','Uses parameterised SQL to pass user-supplied values separately from the SQL statement, rather than concatenating them.','Tests a second booking for the same StudentID and WorkshopID and expects rejection, with the original booking preserved.','Restricts capacity edits to authorised staff with suitable roles/permissions and explains protecting the data.','Proposes separate regular backups with tested restoration and explains recovery after loss/corruption.'],
        model:'Use WorkshopID and BookingID as primary keys. Enforce the WorkshopID foreign key, and a UNIQUE(WorkshopID, StudentID) constraint. Use parameterised SQL, such as placeholders bound to user-supplied values, so those values are treated as data rather than SQL instructions. Test a second booking of the same workshop for the same student: the duplicate must be rejected and the original retained. Restrict capacity updates to authorised staff roles. Keep separate regular backups and test restoration to support recovery. Equivalent constraints, tests and explained controls are acceptable; exact SQL syntax is not required.',
        mistake:'A foreign key alone does not stop the same student booking twice. Parameterised SQL helps prevent SQL injection; it does not replace access control or validation.'}
    ]}
];

practiceSets.push(
  {id:'year11-programming',revision:1,year:11,title:'Year 11 · Programming and problem-solving',minutes:45,
    description:'Selection, loops, functions, lists, files and testing. Eight short answers and two extended responses; 30 marks.',questions:[
    {id:'y11-p1',type:'Short answer',title:'Trace a while loop',topic:'Iteration',chapter:'loops',
      prompt:'State the printed total and the final value of n.',code:'n = 1\ntotal = 0\nwhile n <= 3:\n    total = total + n\n    n = n + 1\nprint(total)',
      criteria:['Printed total is 6.','Final n is 4.'],model:'Printed output: 6. Final n: 4. The loop adds 1, 2 and 3, then stops when n becomes 4.',mistake:'The terminating condition is checked again after n changes. The final n is not the last value added.'},
    {id:'y11-p2',type:'Short answer',title:'Convert input before calculating',topic:'Types and operators',chapter:'values',
      prompt:'A price calculator uses quantity = input("Quantity: ") and then total = quantity * 3. If the user enters 4, explain the problem and give a corrected quantity assignment. Assume valid whole-number input.',
      criteria:['Explains that input returns the string "4", so multiplying by 3 repeats it to produce "444" instead of numeric 12.','Converts the input to an integer, for example quantity = int(input("Quantity: ")).'],
      model:'input returns a string. "4" * 3 produces "444". Use quantity = int(input("Quantity: ")) before multiplying to obtain 12.',mistake:'Changing the prompt does not convert the value. Validation of invalid input is outside this question.'},
    {id:'y11-p3',type:'Short answer',title:'Evaluate a combined condition',topic:'Selection',chapter:'selection',
      prompt:'Admission requires age >= 12 and has_permission. Evaluate the condition for age = 11 and has_permission = True, then explain why.',
      criteria:['The combined condition evaluates to False.','Explains that both parts must be true with and, but 11 >= 12 is false.'],
      model:'False. Permission is true, but the age requirement is false. An and expression requires both conditions to be true.',mistake:'Permission does not override the age requirement. That would require a different admission rule.'},
    {id:'y11-p4',type:'Short answer',title:'Use a function return value',topic:'Functions',chapter:'functions',
      prompt:'State the printed result and identify the argument passed to double.',code:'def double(number):\n    return number * 2\n\nresult = double(6) + 1\nprint(result)',
      criteria:['Printed result is 13.','The argument passed is 6.'],model:'double(6) returns 12, so result becomes 13. The argument is 6; number is the parameter name.',mistake:'An argument is the supplied value. A return value can be used in a larger expression.'},
    {id:'y11-p5',type:'Short answer',title:'Check list indices',topic:'One-dimensional lists',chapter:'arrays',
      prompt:'names = ["Ari", "Bo", "Cam"]. State the value of names[1] and explain what happens when names[3] is evaluated.',
      criteria:['names[1] is "Bo".','names[3] raises IndexError because valid indices are 0, 1 and 2.'],model:'names[1] is "Bo". names[3] is outside the list and raises IndexError; the last item is names[2].',mistake:'List indices start at zero. Index 3 does not refer to the third item.'},
    {id:'y11-p6',type:'Short answer',title:'Preserve a score history',topic:'Text files',chapter:'files',
      prompt:'A game must add a score to the end of an existing text file without removing earlier scores. State a suitable Python file mode and explain why write mode "w" is unsuitable.',
      criteria:['Uses append mode "a".','Explains that opening an existing file in mode "w" truncates its existing contents.'],model:'Use mode "a" to append. Mode "w" empties an existing file when it is opened, losing earlier history.',mistake:'Appending still requires a newline separator when storing one score per line.'},
    {id:'y11-p7',type:'Short answer',title:'Handle an invalid conversion',topic:'Exceptions',chapter:'files',
      prompt:'A user types "three" when int(input("Lives: ")) runs. Name the exception and describe a suitable response that keeps the program usable.',
      criteria:['Names ValueError.','Catches the conversion failure and explains the whole-number requirement before requesting another input, or returns safely to an input screen.'],model:'The conversion raises ValueError. Handle it with try/except, display a clear whole-number message and allow another attempt.',mistake:'Do not silently substitute a valid value without telling the user. This is not a file-not-found error.'},
    {id:'y11-p8',type:'Short answer',title:'Expose an incorrect comparison',topic:'Testing',chapter:'selection',
      prompt:'The requirement says orders of $50 or more receive free delivery. The code incorrectly uses order_total > 50. Give the input that exposes this error and state both the required and incorrect outcomes.',
      criteria:['Uses an order total of exactly $50.','States that free delivery is required, but the incorrect comparison selects the charged-delivery branch.'],model:'Test $50. Expected: free delivery. Actual with > 50: charged delivery. The comparison should include equality.',mistake:'$49 and $51 do not distinguish > from >= at this boundary.'},
    {id:'y11-p9',type:'Extended response',title:'Summarise reading sessions',topic:'Algorithm design',chapter:'arrays',
      prompt:'A list stores non-negative whole minutes for each reading session. Write pseudocode or Python to display the number of sessions, total minutes and number of sessions lasting at least 20 minutes. Handle an empty list. Give one non-empty test containing exactly 20 and one empty-list test, with all expected outputs.',
      criteria:['Correctly obtains the number of sessions.','Initialises total and the qualifying-session count to zero.','Visits every session and adds its minutes to the total.','Increments the qualifying count only for values >= 20.','Handles the empty list without indexing errors and displays zero for all three results.','Gives a correct non-empty test containing 20, with all three expected outputs.','Gives [] with expected count 0, total 0 and qualifying count 0.'],
      model:'total = 0\nlong_sessions = 0\nfor minutes in sessions:\n    total = total + minutes\n    if minutes >= 20:\n        long_sessions = long_sessions + 1\nprint(len(sessions), total, long_sessions)\n\n[10, 20, 25] → 3 sessions, total 55, 2 sessions of at least 20 minutes. [] → 0, 0, 0. The loop naturally handles an empty list. Equivalent algorithms are acceptable.',mistake:'Exactly 20 qualifies. Count qualifying sessions separately from their combined duration.'},
    {id:'y11-p10',type:'Extended response',title:'Plan a manageable game feature',topic:'Functions, requirements and testing',chapter:'functions',
      prompt:'A Pygame collection game adds 10 points when an active item is collected. Each item can score only once; a new game starts at zero. Describe two functional requirements and one measurable usability requirement. Design a function interface for collecting an item, including inputs, returned values and the repeated-collection rule. Give a repeated-collection test with expected results. No drawing code is required.',
      criteria:['States that collecting an active item increases score by exactly 10.','States that starting a new game resets the score to zero.','States a measurable usability requirement, such as score text remaining readable at a specified window size during a peer trial.','Identifies score and item-active status as function inputs or equivalent explicit state.','Returns the updated score and item-active status, or an equivalent clearly defined result.','Awards points only if active and then marks the item inactive, so later calls do not award them again.','Tests repeated collection: for example score 0 with an active item becomes 10/inactive, then remains 10/inactive.'],
      model:'Functional: an active collected item awards 10 points; a new game begins at zero. Usability: in an 800 × 600 window, a peer can read the score throughout a two-minute trial. A collect(score, active) function returns score and active. If active, add 10 and set active to False; otherwise leave both unchanged. Test collect(0, True) → (10, False), then collect(10, False) → (10, False). Other measurable usability targets and equivalent function designs are acceptable.',mistake:'A requirement should be checkable. A function that increases the score every frame while overlapping an item violates the one-award rule.'}
  ]},
  {id:'year11-data-networks',revision:1,year:11,title:'Year 11 · Data, networks and security',minutes:45,
    description:'Relational data, SQL, network communication and protective controls. Eight short answers and two extended responses; 30 marks.',questions:[
    {id:'y11-d1',type:'Short answer',title:'Turn data into information',topic:'Data and information',chapter:'database-foundations',
      prompt:'A sensor stores temperatures 18, 21 and 24 degrees Celsius at three stated times. Distinguish these readings as data from one useful piece of information produced from them.',
      criteria:['Identifies the individual recorded readings as data.','Derives a useful contextual statement, such as the mean recorded temperature being 21 degrees Celsius or the readings increasing over the three times.'],model:'The individual readings are data. Calculating their mean produces the information that the mean recorded temperature was 21 degrees Celsius during those three observations.',mistake:'Information needs meaning in context. Do not claim the readings establish temperatures outside the observed times.'},
    {id:'y11-d2',type:'Short answer',title:'Distinguish network scope',topic:'Networks',chapter:'networks',
      prompt:'Computers in one school building share a local network. The school connects to a campus in another city through a provider network. Identify the local network type and the wider network type.',
      criteria:['Identifies the building network as a LAN.','Identifies the network spanning the distant sites as a WAN.'],model:'The building uses a local area network (LAN). Communication across distant sites uses a wide area network (WAN).',mistake:'Wireless describes a connection medium, not the distinction between local and wide geographic scope.'},
    {id:'y11-d3',type:'Short answer',title:'Choose a switch and a router',topic:'Network devices',chapter:'networks',
      prompt:'Explain the different roles of a switch connecting classroom computers and a router connecting the school LAN to another IP network.',
      criteria:['Explains that a switch forwards frames between devices on the local network, typically using destination MAC addresses.','Explains that a router forwards IP packets between networks using network addressing/routing information.'],model:'The switch connects local devices and forwards frames using MAC-address information. The router forwards packets between the school network and other IP networks.',mistake:'A switch and a router do not perform identical forwarding roles.'},
    {id:'y11-d4',type:'Short answer',title:'Distinguish addressing roles',topic:'Addressing',chapter:'addressing',
      prompt:'Explain the role of an IP address and a MAC address when communicating across networks.',
      criteria:['Explains that an IP address supports logical addressing and routing between IP networks.','Explains that a MAC address identifies a network interface for local-link frame delivery.'],model:'IP addresses support routing to the destination across networks. MAC addresses support frame delivery on the local link. As a packet crosses routed links, link-layer addressing changes.',mistake:'Do not describe a MAC address as the Internet-wide routing address or assume it can never be changed.'},
    {id:'y11-d5',type:'Short answer',title:'Explain packet sequence information',topic:'Communication',chapter:'networks',
      prompt:'A reliable transport protocol divides a message into numbered pieces. Explain why sequence information is useful if pieces arrive out of order, and what should happen if a piece is missing.',
      criteria:['Explains that sequence information supports placing pieces back into the correct order.','Explains that the reliable protocol detects missing data and arranges retransmission, rather than treating the incomplete message as complete.'],model:'Sequence information lets the receiver order the data correctly. Missing data must be detected and retransmitted by the reliable protocol.',mistake:'Not every protocol guarantees reliable delivery. This question explicitly describes a reliable transport protocol.'},
    {id:'y11-d6',type:'Short answer',title:'Avoid repeated supplier details',topic:'Database design',chapter:'normalisation',
      prompt:'A Stock table repeats SupplierName and SupplierPhone on every stock-item row. Each SupplierID identifies one supplier. Identify an update problem and explain a suitable design improvement.',
      criteria:['Explains that changing a supplier phone in only some rows creates inconsistent supplier details.','Moves supplier details to a separate Supplier table keyed by SupplierID and references it from Stock.'],model:'Partial updates can leave different phone numbers for the same supplier. Store SupplierID, SupplierName and SupplierPhone once in Supplier, with SupplierID referenced from Stock.',mistake:'Removing repeated phone numbers without retaining the supplier relationship loses useful data.'},
    {id:'y11-d7',type:'Short answer',title:'Order a filtered report',topic:'SQL',chapter:'sql-basics',
      prompt:'Book(BookID, Title, Available) stores Available as 1 or 0. Write SQL to list Title for available books, sorted alphabetically by Title.',
      criteria:['Selects Title from Book with WHERE Available = 1.','Uses ORDER BY Title ASC (or omits ASC because ascending is the default).'],model:'SELECT Title\nFROM Book\nWHERE Available = 1\nORDER BY Title ASC;\nEquivalent correct SQL is acceptable.',mistake:'ORDER BY sorts the result; it does not select which books qualify.'},
    {id:'y11-d8',type:'Short answer',title:'Reduce malware risk',topic:'Security',chapter:'security-threats',
      prompt:'Students are asked to run an unexpected executable attachment on school computers. Propose one preventive action and one recovery measure if malware damages local files.',
      criteria:['Does not run the untrusted attachment and reports it through the school process, or explains an appropriate application-control measure.','Uses a known-clean separate backup to restore damaged files after the device has been appropriately contained/cleaned.'],model:'Do not execute the attachment; report it to school support. Following containment and clean-up, recover damaged data from a separate known-clean backup.',mistake:'A backup does not stop malware executing. Restoring onto an actively infected device may damage the restored files again.'},
    {id:'y11-d9',type:'Extended response',title:'Design an equipment catalogue',topic:'Relational design and queries',chapter:'entities-relationships',
      prompt:'A club stores equipment items and their suppliers. One supplier supplies many items; each item has one supplier. Design Supplier and Item tables with suitable fields, keys and a relationship. Explain one benefit of separating supplier details. Write SQL to list item names costing less than $25 from Item(ItemID, ItemName, Cost, SupplierID). Include expected results for a $24 item and a $25 item.',
      criteria:['Defines Supplier with SupplierID as primary key and suitable supplier details.','Defines Item with ItemID as primary key and the stated item fields.','Identifies Item.SupplierID as a foreign key referencing Supplier.SupplierID.','Explains that storing supplier details once reduces duplication or inconsistent updates.','Uses SELECT ItemName FROM Item with WHERE Cost < 25.','Correctly expects the $24 item to be included.','Correctly expects the $25 item to be excluded.'],model:'Supplier(SupplierID PK, SupplierName, SupplierPhone). Item(ItemID PK, ItemName, Cost, SupplierID FK). Item.SupplierID references Supplier.SupplierID, giving one supplier many items. Changing a phone number needs one supplier update.\nSELECT ItemName FROM Item WHERE Cost < 25;\nA $24 item is included; a $25 item is excluded. Equivalent fields and correct SQL are acceptable.',mistake:'Less than excludes exactly $25. The supplier key belongs in each item record to express this relationship.'},
    {id:'y11-d10',type:'Extended response',title:'Plan a small classroom network',topic:'Network design',chapter:'network-design',
      prompt:'A classroom needs 12 fixed computers to share a printer and reach another school network. Describe a suitable wired layout, device roles, one reason for the chosen connection medium, one access control and two checks with expected outcomes. Address both local communication and communication beyond the LAN.',
      criteria:['Describes a suitable star layout with fixed computers connected to a central switch.','Explains how the switch supports communication among local computers and the printer.','Uses a router to reach another IP network and explains its role.','Gives a justified wired-medium choice, such as suitable Ethernet cabling for stable fixed workstations.','Proposes individual accounts or suitable printer/network permissions and explains restricting unauthorised access.','Gives a local test with an expected result, such as an authorised computer successfully printing a test page.','Gives an external-network test with an expected result, such as reaching a known permitted school service through the router.'],model:'Connect the 12 computers and a network-capable printer to a suitably sized switch in a star. Connect the switch to the school router for other IP networks. Suitable Ethernet cabling suits fixed workstations and avoids relying on shared radio conditions. Apply individual accounts and appropriate printer permissions. Test that an authorised workstation prints a test page, and that it reaches a known permitted service on another network. Other justified media and concrete checks meeting these requirements are acceptable.',mistake:'A successful local print test alone does not prove routing works. Device counts must fit the available switch ports, including uplinks.'}
  ]},
  {id:'year12-programming',revision:1,year:12,title:'Year 12 · Structures, algorithms and objects',minutes:45,
    description:'Two-dimensional lists, dictionaries, searching, sorting and object-oriented design. Eight short answers and two extended responses; 30 marks.',questions:[
    {id:'y12-p1',type:'Short answer',title:'Update a dictionary entry',topic:'Dictionaries',chapter:'unit3-structures',
      prompt:'State the final value of items["gem"] and the number of dictionary entries.',code:'items = {"gem": 10, "key": 0}\nitems["gem"] = 15\nitems["coin"] = 5',
      criteria:['items["gem"] is 15.','The dictionary has 3 entries.'],model:'The existing "gem" value is replaced with 15. Adding the new "coin" key gives three entries.',mistake:'Assigning to an existing key updates it; it does not create a second entry with that key.'},
    {id:'y12-p2',type:'Short answer',title:'Trace an alias',topic:'Two-dimensional lists',chapter:'unit3-structures',
      prompt:'State the final value of grid and explain why alias affects it.',code:'grid = [[0, 1], [2, 3]]\nalias = grid\nalias[0][1] = 9',
      criteria:['Final grid is [[0, 9], [2, 3]].','Explains that alias and grid reference the same list object; assignment did not copy it.'],model:'grid becomes [[0, 9], [2, 3]]. alias = grid binds another name to the same object, so the indexed change is visible through both names.',mistake:'A second variable name is not automatically an independent copy.'},
    {id:'y12-p3',type:'Short answer',title:'Trace a linear search',topic:'Searching',chapter:'unit3-search',
      prompt:'A linear search visits [9, 4, 7, 2] from left to right and stops at the first match for 7. State the returned zero-based index and number of item-to-target comparisons.',
      criteria:['Returns index 2.','Makes 3 item-to-target comparisons.'],model:'Index 2, after comparisons with 9, 4 and 7. The search stops on the match.',mistake:'The returned index and number of comparisons differ because indices start at zero.'},
    {id:'y12-p4',type:'Short answer',title:'Insert into a sorted prefix',topic:'Sorting',chapter:'unit3-sort',
      prompt:'During ascending insertion sort, [3, 6] is the sorted prefix of [3, 6, 2, 5]. Insert the next value, 2. State the resulting full list and identify which existing values shift right.',
      criteria:['The list becomes [2, 3, 6, 5].','Both 6 and 3 shift one position right before 2 is inserted.'],model:'[2, 3, 6, 5]. Shift 6 and then 3 right, leaving the insertion position for 2. The final 5 is not processed in this step.',mistake:'This is one insertion step, not a request to finish sorting the whole list.'},
    {id:'y12-p5',type:'Short answer',title:'Trace a binary-search step',topic:'Searching',chapter:'unit3-search',
      prompt:'An ascending list is [2, 5, 8, 11, 14, 17, 20]. Binary search for 17 starts with low = 0 and high = 6 and uses mid = (low + high) // 2. State the first midpoint value and the updated low/high bounds after comparing it with 17.',
      criteria:['The first midpoint value is 11 (at index 3); the required answer is the value.','Updates low to 4 and leaves high at 6.'],model:'mid = 3, so compare 11 with 17. Since the target is larger, set low = 4; high remains 6.',mistake:'The midpoint index is not the midpoint value. Exclude the already-compared midpoint from the next interval.'},
    {id:'y12-p6',type:'Short answer',title:'Keep object state separate',topic:'Objects',chapter:'unit3-objects',
      prompt:'Two Player objects each initialise self.score = 0 in their constructor. Explain what self.score represents and what happens to the second player’s score when only the first player’s score increases to 10.',
      criteria:['Identifies self.score as an instance attribute belonging to an individual Player object.','The second player remains at 0 because the two instances maintain separate score attributes.'],model:'self.score is an instance attribute. Updating the first instance to 10 leaves the second instance at 0.',mistake:'Do not confuse instance attributes with a shared class attribute.'},
    {id:'y12-p7',type:'Short answer',title:'Justify an inheritance relationship',topic:'Inheritance',chapter:'unit3-inheritance',
      prompt:'A design proposes Player inherits from Actor, while ScoreFile inherits from Player. Identify the suitable relationship and explain why the other is unsuitable.',
      criteria:['Player inheriting from Actor is suitable when a player is a kind of actor with shared actor state/behaviour.','ScoreFile is not a kind of Player; file handling should have a separate responsibility or be used by another object rather than inheriting player behaviour.'],model:'A Player is an Actor, so shared actor movement can be inherited. A ScoreFile is not a Player; it has a different responsibility and should be separate.',mistake:'Wanting to reuse a method is not by itself a sound is-a relationship.'},
    {id:'y12-p8',type:'Short answer',title:'Handle a missing optional history file',topic:'Reliability',chapter:'unit3-reliability',
      prompt:'On the first run, a game has no optional score-history file. Name the exception raised by attempting to open the missing file for reading and describe a suitable recovery response.',
      criteria:['Names FileNotFoundError.','Starts with an empty history and an appropriate message/default while allowing the game to continue.'],model:'Catch FileNotFoundError. Treat history as empty on the first run and allow normal play, explaining the absence if appropriate.',mistake:'Do not crash or fabricate past scores. Other file errors may need a different message or response.'},
    {id:'y12-p9',type:'Extended response',title:'Process a grid of readings',topic:'Two-dimensional algorithms',chapter:'unit3-structures',
      prompt:'A non-empty rectangular grid contains non-negative whole sensor readings, with at least one item in each row. Write pseudocode or Python to find the total and count readings greater than 10. Use nested iteration. Give one test grid containing exactly 10 with expected results, and explain how a grid containing only zeroes is handled.',
      criteria:['Initialises total and the greater-than-10 count to zero.','Uses an outer loop to visit every row.','Uses an inner loop to visit each item in the current row.','Adds every visited reading to the total exactly once.','Increments the count only for values > 10, excluding exactly 10.','Gives a grid containing 10 with the correct total and qualifying count.','Explains that an all-zero grid returns total 0 and qualifying count 0 without errors.'],model:'total = 0\nabove = 0\nfor row in grid:\n    for reading in row:\n        total = total + reading\n        if reading > 10:\n            above = above + 1\nprint(total, above)\n\n[[10, 11], [0, 15]] → total 36, count 2. [[0, 0], [0, 0]] → total 0, count 0. Equivalent nested algorithms are acceptable.',mistake:'Do not add a row list to a numeric total or use >= when the requirement says greater than.'},
    {id:'y12-p10',type:'Extended response',title:'Separate game responsibilities',topic:'Object-oriented design and testing',chapter:'unit3-inheritance',
      prompt:'A game has a player, patrolling hazards and collectible items indexed by unique IDs. Explain shared Actor state, inheritance and specialised update behaviour. Specify a suitable item lookup structure. Describe how drawing stays separate from gameplay changes, then give one test for independent object state and one test for an overridden update method, with expected outcomes.',
      criteria:['Places shared position and suitable movement/bounds behaviour in Actor.','Makes Player and Hazard subclasses that inherit the shared actor features.','Explains specialised update implementations for keyboard-driven Player and predictable-patrol Hazard.','Uses a dictionary mapping unique item IDs to item data for lookup.','Drawing reads state without changing score, position or other gameplay state.','Tests two instances and expects changing one position/score not to change the other instance.','Tests a subclass update with a stated input/initial state and a concrete expected movement or patrol result.'],model:'Actor holds position and common movement/bounds logic. Player and Hazard inherit it, overriding update for keyboard input and a timed patrol respectively. A dictionary maps item IDs to item data. draw reads the current state and renders it, without moving actors or adding score. Test two players initially at x=10: moving one to x=20 leaves the other at x=10. For a Hazard at x=0 moving one tile right per update, one permitted update produces x=1 tile. Equivalent explicit designs and tests are acceptable.',mistake:'Drawing that changes gameplay can make behaviour depend on how often the screen is redrawn. Test responsibilities, not only class names.'}
  ]},
  {id:'year12-data-security',revision:1,year:12,title:'Year 12 · Relational data and security',minutes:45,
    description:'Relational design, SQL, transactions, cryptography and security controls. Eight short answers and two extended responses; 30 marks.',questions:[
    {id:'y12-d1',type:'Short answer',title:'Identify a functional dependency',topic:'Relational design',chapter:'unit4-design',
      prompt:'Each ProductID determines exactly one ProductName and Price. State one functional dependency and explain what it means.',
      criteria:['States ProductID → ProductName or ProductID → Price (or the combined dependency).','Explains that a particular ProductID determines one associated value for the dependent attribute under the stated rule.'],model:'ProductID → ProductName. For a given ProductID, there is one associated ProductName under the stated business rule.',mistake:'A sample table alone cannot establish every business dependency; use the rule supplied in the question.'},
    {id:'y12-d2',type:'Short answer',title:'Use a composite key',topic:'Relational design',chapter:'unit4-design',
      prompt:'Enrolment(StudentID, CourseID, EnrolmentDate) stores at most one enrolment for a student in a course. A student can take many courses and each course has many students. Identify a suitable composite primary key and explain why either individual ID is insufficient.',
      criteria:['Uses the pair (StudentID, CourseID) as the composite primary key.','Explains that StudentID repeats across courses and CourseID repeats across students, while the pair identifies one enrolment.'],model:'Use (StudentID, CourseID). Neither field alone is unique, but the pair is unique under the stated one-enrolment rule.',mistake:'Do not claim StudentID or CourseID alone uniquely identifies an enrolment in this many-to-many relationship.'},
    {id:'y12-d3',type:'Short answer',title:'Count bookings by workshop',topic:'Aggregate SQL',chapter:'unit4-sql',
      prompt:'Booking(BookingID, WorkshopID, StudentID) contains confirmed bookings only. Write SQL to display WorkshopID and the number of bookings for each WorkshopID present in Booking.',
      criteria:['Selects WorkshopID and COUNT(*) from Booking.','Groups the result using GROUP BY WorkshopID.'],model:'SELECT WorkshopID, COUNT(*) AS BookingCount\nFROM Booking\nGROUP BY WorkshopID;\nAliases and equivalent correct aggregate queries are acceptable.',mistake:'This query reports workshops present in Booking. Including zero-booking workshops would require their separate workshop records and a suitable join.'},
    {id:'y12-d4',type:'Short answer',title:'Target an update',topic:'SQL data modification',chapter:'unit4-sql',
      prompt:'Workshop(WorkshopID, Title, Capacity) has a unique WorkshopID. Write SQL to set Capacity to 24 only for WorkshopID 7.',
      criteria:['Uses UPDATE Workshop SET Capacity = 24.','Uses WHERE WorkshopID = 7 to restrict the change.'],model:'UPDATE Workshop\nSET Capacity = 24\nWHERE WorkshopID = 7;',mistake:'Without WHERE, the update changes every workshop row.'},
    {id:'y12-d5',type:'Short answer',title:'Use a transaction',topic:'Database reliability',chapter:'unit4-sql',
      prompt:'An application must insert an Order row and its OrderLine rows together. Explain the role of a transaction and the response if one required insert fails.',
      criteria:['Explains that the related changes are treated as one unit and committed together only when all required operations succeed.','Rolls back the transaction on failure so a partial order is not left committed.'],model:'Run the related inserts in one transaction. Commit after all required inserts succeed; roll back if any fails so the database does not retain only part of the order.',mistake:'A transaction does not automatically validate every business rule. The application still needs suitable error handling and constraints.'},
    {id:'y12-d6',type:'Short answer',title:'Distinguish encryption and hashing',topic:'Cryptography',chapter:'unit4-crypto',
      prompt:'Distinguish encrypting a message for later recovery from hashing a message to produce a comparison digest.',
      criteria:['Explains that encryption can be reversed using the appropriate key to recover the message.','Explains that hashing produces a digest for comparison and is not designed to recover the original message.'],model:'Encryption transforms plaintext into ciphertext that can be decrypted with the appropriate key. Hashing produces a digest; comparing digests can help detect changes, but does not recover the message.',mistake:'Hashing is not encryption without a key. A digest alone does not establish who created the message.'},
    {id:'y12-d7',type:'Short answer',title:'Compare key arrangements',topic:'Cryptography',chapter:'unit4-crypto',
      prompt:'State the key arrangement used by symmetric encryption and by asymmetric encryption.',
      criteria:['Symmetric encryption uses a shared secret key for encryption and decryption.','Asymmetric encryption uses a related public/private key pair; in public-key encryption the public key encrypts and the corresponding private key decrypts.'],model:'Symmetric encryption uses a shared secret key. Asymmetric encryption uses a public/private key pair; a message encrypted with a recipient’s public key is decrypted using the corresponding private key.',mistake:'Do not describe the public key as secret. Digital signatures use the pair for a different operation from encrypting a confidential message.'},
    {id:'y12-d8',type:'Short answer',title:'Separate authentication and authorisation',topic:'Access control',chapter:'unit4-controls',
      prompt:'A staff member signs in successfully but cannot change a student record. Explain authentication and authorisation in this example.',
      criteria:['Authentication checks the staff member’s claimed identity during sign-in.','Authorisation determines permitted actions, so successful sign-in does not itself grant record-editing rights.'],model:'Authentication establishes the claimed account identity. Authorisation checks whether that account is allowed to edit the record; an authenticated account can still lack permission.',mistake:'Access permissions and identity checks solve different problems.'},
    {id:'y12-d9',type:'Extended response',title:'Remove a transitive dependency',topic:'Normalisation and integrity',chapter:'unit4-design',
      prompt:'Asset(AssetID, AssetName, RoomID, RoomName) stores one room per asset. AssetID is the primary key, RoomID determines RoomName, and room names may repeat. Explain the transitive dependency and an update anomaly. Decompose the table into two suitable tables with keys and a relationship. Explain a rule preventing an asset from referencing a non-existent room. Assume all attributes hold atomic values.',
      criteria:['Identifies AssetID → RoomID → RoomName as the transitive dependency.','Explains an update anomaly: changing a room name in only some asset rows leaves inconsistent names for the same RoomID.','Defines Room(RoomID, RoomName) with RoomID as primary key.','Defines Asset(AssetID, AssetName, RoomID) with AssetID as primary key.','Identifies Asset.RoomID as a foreign key referencing Room.RoomID.','Explains that storing the room name once removes this transitive dependency from Asset and avoids repeated room-name updates.','Requires an enforced foreign-key constraint so a non-null Asset.RoomID must refer to an existing Room row.'],model:'AssetID → RoomID and RoomID → RoomName, so RoomName depends transitively on AssetID. Partial room-name edits can make the same RoomID appear with different names. Decompose into Room(RoomID PK, RoomName) and Asset(AssetID PK, AssetName, RoomID FK). Reference Room.RoomID from Asset.RoomID and enforce the foreign-key constraint. RoomName is stored once per room; a name change no longer requires edits to each asset. RoomName is not a suitable key because names may repeat.',mistake:'Keep the linking RoomID in Asset. Decomposition without the relationship loses which room contains each asset.'},
    {id:'y12-d10',type:'Extended response',title:'Protect a school booking service',topic:'Security analysis and evaluation',chapter:'unit4-controls',
      prompt:'A school booking service faces stolen staff passwords, accidental record deletion and attempts by student accounts to edit capacity. Propose and justify controls for each risk, plus useful audit logging. Describe one permission test and one recovery test with expected outcomes. Explain one remaining limitation after the controls are applied.',
      criteria:['Proposes multi-factor authentication and explains why a stolen password alone should be insufficient to sign in.','Restricts capacity changes to authorised staff and explains least privilege for student accounts.','Uses separate regular backups and explains recovery after accidental deletion.','Logs relevant changes with actor, time and action/result to support investigation.','Tests a student capacity-edit attempt and expects rejection with capacity unchanged.','Tests restoration from a known backup in a safe test environment and expects the selected records to be recovered correctly.','Explains a relevant residual limitation, such as deletion after the latest backup causing some data loss, compromised recovery channels, or logs needing review/protection.'],model:'Use suitable MFA for staff sign-in; enforce staff-only capacity-edit permissions at the application/database boundary. Keep separate regular backups for recovery and log who changed a booking or capacity, when, and whether the operation succeeded. Test that a student edit is rejected and capacity remains unchanged. Restore a known backup into a safe test environment and compare recovered records with expected records. Some changes since the last backup may still be lost; controls reduce risk rather than eliminate it. Equivalent justified controls, concrete tests and relevant limitations are acceptable.',mistake:'Hiding a button is not an enforced permission check. A backup must be restorable, and logging alone does not prevent an unauthorised change.'}
  ]}
);
